-- Haradon races: start positions, spells, items, action bars and level stats
-- Generated by NetCoreClient/tools/M425Patch from the 425 tables. Do not edit; re-run tools/build-m425.sh.
SET NAMES utf8mb4;

DELETE FROM `playercreateinfo` WHERE `race` BETWEEN 10 AND 14;
DELETE FROM `playercreateinfo_spell` WHERE `race` BETWEEN 10 AND 14;
DELETE FROM `playercreateinfo_item` WHERE `race` BETWEEN 10 AND 14;
DELETE FROM `playercreateinfo_action` WHERE `race` BETWEEN 10 AND 14;
DELETE FROM `player_levelstats` WHERE `race` BETWEEN 10 AND 14;

UPDATE `player_levelstats` p JOIN (SELECT `class`, `level`, ROUND(AVG(`spi`)) AS `spi` FROM `player_levelstats` WHERE `race` < 10 GROUP BY `class`, `level`) w ON w.`class` = p.`class` AND w.`level` = p.`level` SET p.`spi` = w.`spi` WHERE p.`race` BETWEEN 10 AND 14;
